Circles with centers of $(2,2)$ and $(17,10)$ are both tangent to the $x$-axis. What is the distance between the closest points of the two circles?

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>

using namespace std;

int main() {
    double x1 = 2, y1 = 2, x2 = 17, y2 = 10;
    double radius1 = sqrt(pow(x1, 2) + pow(y1, 2));
    double radius2 = sqrt(pow(x2, 2) + pow(y2, 2));
    double distance = sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
    double closestPoint = distance - radius1 - radius2;
    cout << "The distance between the closest points of the two circles is: " << closestPoint << endl;
    return 0;
}

